def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    r, c = next((r, c) for r in range(h) for c in range(w) if g[r][c] == 3)
    dirs = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    d, length = 0, 2

    while True:
        for _ in range(2):
            dr, dc = dirs[d]
            for _ in range(length):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w):
                    # When the expanding spiral reaches the grid edge, complete
                    # the outermost line along the opposite border.
                    for j in range(w):
                        if g[h - 1][j] != 2:
                            g[h - 1][j] = 3
                    return g
                if g[nr][nc] == 2:
                    return g
                r, c = nr, nc
                g[r][c] = 3
            d = (d + 1) % 4
        length += 2
